require_once dirname(__DIR__).'/includes/admin-auth.php';
require_once dirname(__DIR__).'/includes/blog/blog-settings.php';
$user=mg_require_admin_page_any(['admin.blog.view','admin.blog.manage']);if(!mg_admin_permission_user_has($user,'admin.blog.manage')){mg_admin_page_forbidden('admin.blog.manage');}$pdo=mg_db();$schema=mg_blog_schema_ready($pdo);$ready=$schema['ready']&&mg_blog_media_ready($pdo);$notice='';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){if(!mg_verify_csrf((string)($_POST['csrf_token']??''))){$errors[]='Security token expired. Refresh and try again.';}elseif(!$ready){$errors[]='Blog media SQL is required before uploading media.';}else{$id=mg_blog_handle_media_upload($pdo,$user,$errors);if($id){$notice='Blog media uploaded.';}}}$items=$ready?mg_blog_media_items($pdo):[];$page_title='Blog Media | Microgifter Admin';$page_section='account';$header_mode='account';$page_body_class='mg-admin-blog-page';$page_styles=['/assets/css/admin-shell.css','/assets/css/admin-blog.css','/assets/css/admin-blog-settings.css'];$adminActive='blog';require dirname(__DIR__).'/includes/header.php';
?>
<section class="mg-app-shell mg-admin-app"><?php require dirname(__DIR__).'/includes/admin-sidebar.php'; ?><div class="mg-app-workspace mg-admin-workspace"><main class="mg-admin-blog-shell"><header class="mg-admin-blog-hero is-editor"><div><a class="mg-admin-blog-back" href="/admin/blog-posts.php">← Blog manager</a><span class="mg-eyebrow">Content Studio</span><h1>Blog media</h1><p>Upload reusable images for article covers, inline visuals, social previews, and SEO assets.</p></div><div class="mg-admin-blog-actions"><a class="mg-btn mg-btn-soft" href="/admin/blog-settings.php">Settings</a><a class="mg-btn mg-btn-ghost" href="/admin/blog-editor.php">Create post</a></div></header><?php if(!$ready): ?><section class="mg-admin-blog-alert"><strong>SQL migration required.</strong><span>Run <code>database/microgifter_blog_module.sql</code> before uploading media.</span></section><?php endif; ?><?php if($notice!==''): ?><section class="mg-admin-blog-alert is-success"><strong>Uploaded.</strong><span><?= mg_e($notice) ?></span></section><?php endif; ?><?php foreach($errors as $m): ?><section class="mg-admin-blog-alert is-error"><strong>Action failed.</strong><span><?= mg_e((string)$m) ?></span></section><?php endforeach; ?><section class="mg-admin-blog-media-layout"><form class="mg-admin-blog-side-card" method="post" enctype="multipart/form-data" action="/admin/blog-media.php"><?= mg_csrf_field() ?><h2>Upload image</h2><label>Image file<input type="file" name="media_file" accept="image/jpeg,image/png,image/webp,image/gif" required></label><label>Alt text<input type="text" name="alt_text" maxlength="255" placeholder="Describe the image"></label><button class="mg-btn mg-btn-primary" type="submit">Upload media</button><p class="mg-admin-blog-help">JPG, PNG, WebP, or GIF. Maximum 8 MB.</p></form><section class="mg-admin-blog-panel"><div class="mg-admin-blog-media-grid"><?php if(!$ready): ?><div class="mg-admin-blog-empty"><h2>Media table not installed.</h2><p>Import the blog migration to use the media library.</p></div><?php elseif(!$items): ?><div class="mg-admin-blog-empty"><h2>No media yet.</h2><p>Upload reusable blog images here.</p></div><?php else: ?><?php foreach($items as $item): ?><article class="mg-admin-blog-media-card"><div class="mg-admin-blog-media-thumb" style="background-image:url('<?= mg_e((string)$item['file_path']) ?>')"></div><div><strong><?= mg_e((string)$item['file_name']) ?></strong><span><?= mg_e((string)$item['mime_type']) ?> · <?= number_format((int)$item['file_size']) ?> bytes</span><input readonly value="<?= mg_e((string)$item['file_path']) ?>"><small><?= mg_e((string)($item['alt_text']??'')) ?></small></div></article><?php endforeach; ?><?php endif; ?></div></section></section></main></div></section><?php require dirname(__DIR__).'/includes/footer.php'; ?>
